import type {
  EmailCommunicationClass,
  EmailDeliveryPriority,
  EmailLayoutFamily,
  EmailPurposeFamily,
  UnsubscribePolicy,
} from '@/lib/email/emailCommunicationClasses';

export interface EmailPurposeDefinition {
  templateKey: string;
  family: EmailPurposeFamily;
  communicationClass: EmailCommunicationClass;
  layoutFamily: EmailLayoutFamily;
  /** Preference category key for category-specific unsubscribe */
  preferenceCategory: string;
  defaultPriority: EmailDeliveryPriority;
  unsubscribePolicy: UnsubscribePolicy;
  subjectTemplate: string;
  preheaderTemplate: string;
  headlineTemplate: string;
  bodyTemplate: string;
  ctaLabel?: string;
  variants?: string[];
  /** Backend event type that triggers this email, when wired */
  eventType?: string;
  /** Whether a backend trigger is currently connected */
  wired: boolean;
}

type PurposeSeed = Omit<EmailPurposeDefinition, 'templateKey'> & { key: string };

function definePurposes(seeds: PurposeSeed[]): Record<string, EmailPurposeDefinition> {
  const registry: Record<string, EmailPurposeDefinition> = {};
  for (const seed of seeds) {
    const { key, ...rest } = seed;
    registry[key] = { templateKey: key, ...rest };
  }
  return registry;
}

