export const EMAIL_PURPOSE_REGISTRY: Record<string, EmailPurposeDefinition> = definePurposes([
  ...ACCOUNT_AUTH,
  ...ONBOARDING,
  ...BUSINESS_INTELLIGENCE,
  ...CRM_LEADS,
  ...OUTREACH_CAMPAIGNS,
  ...EMAIL_COMMUNICATION,
  ...SALES_PROPOSALS,
  ...INVOICES_MONEY,
  ...CALENDAR_MEETINGS,
  ...SOCIAL_MARKETING,
  ...MCP_AUTOMATION,
  ...PLATFORM_INTEGRATIONS,
]);

export function getEmailPurpose(templateKey: string): EmailPurposeDefinition | null {
  return EMAIL_PURPOSE_REGISTRY[templateKey] || null;
}

export function listEmailPurposes(filter?: { family?: EmailPurposeFamily; wired?: boolean }): EmailPurposeDefinition[] {
  return Object.values(EMAIL_PURPOSE_REGISTRY).filter((purpose) => {
    if (filter?.family && purpose.family !== filter.family) return false;
    if (filter?.wired !== undefined && purpose.wired !== filter.wired) return false;
    return true;
  });
}

export function resolvePurposeByEventType(eventType: string): EmailPurposeDefinition | null {
  return Object.values(EMAIL_PURPOSE_REGISTRY).find((p) => p.eventType === eventType) || null;
}

export function countEmailPurposes(): { total: number; wired: number; unwired: number } {
  const all = Object.values(EMAIL_PURPOSE_REGISTRY);
  const wired = all.filter((p) => p.wired).length;
  return { total: all.length, wired, unwired: all.length - wired };
}

